-- Subject set with the capability booleans: the same list with an EXISTS per row per transition.
SELECT Id, SectorId, ClientId, KindId, Title, Brief, Hazard, Fee, Deadline, RequiredCertId, BookedByUserId, AssignedSquadronId, StatusId, Notes, ARRAY<BOOL>[((`Missions`.`StatusId` IN ('claimed') AND EXISTS (SELECT 1 FROM `SquadronMemberships` `ca4` WHERE `ca4`.`UserId` = 'f0000000-0000-4000-8000-000000000006' AND `ca4`.`SquadronId` = `Missions`.`AssignedSquadronId` AND EXISTS (SELECT 1 FROM `Squadrons` `ca5` WHERE `ca5`.`Id` = `ca4`.`SquadronId` AND EXISTS (SELECT 1 FROM `Wings` `ca6` WHERE `ca6`.`Id` = `ca5`.`WingId` AND `ca6`.`SectorId` = 'a1111111-1111-4111-8111-111111111111'))))), (`Missions`.`StatusId` IN ('underway')), (`Missions`.`StatusId` IN ('on_hold')), (`Missions`.`StatusId` IN ('open')), (`Missions`.`StatusId` = 'underway')] AS zzCapabilityChecks FROM Missions WHERE (`Missions`.`SectorId` = 'a1111111-1111-4111-8111-111111111111') AND (EXISTS (SELECT 1 FROM `SquadronMemberships` `ca1` WHERE `ca1`.`UserId` = 'f0000000-0000-4000-8000-000000000006' AND `ca1`.`SquadronId` = `Missions`.`AssignedSquadronId` AND EXISTS (SELECT 1 FROM `Squadrons` `ca2` WHERE `ca2`.`Id` = `ca1`.`SquadronId` AND EXISTS (SELECT 1 FROM `Wings` `ca3` WHERE `ca3`.`Id` = `ca2`.`WingId` AND `ca3`.`SectorId` = 'a1111111-1111-4111-8111-111111111111'))) OR `Missions`.`BookedByUserId` = 'f0000000-0000-4000-8000-000000000006') ORDER BY `Deadline` ASC, `Id` ASC LIMIT 26
